function isTelegramLike(j, messenger, contactMethod) {
  if (contactMethod === 'telegram') return true;
  if (/t\.me|telegram\.me|^@/i.test(String(messenger || ''))) return true;
  if (j.communication_preference === 'telegram') return true;
  return false;
